import Image from 'next/image';

type Props = { variant?: 'primary' | 'reversed'; className?: string; priority?: boolean };

// Lockup SVGs are generated by scripts/build-logo.mjs (wordmark outlined from Baloo 2 ExtraBold).
// Aspect ratio of the lockup viewBox ≈ 5.25 : 1.
export default function Logo({ variant = 'primary', className = 'h-9 w-auto', priority }: Props) {
  return (
    <Image
      src={variant === 'primary' ? '/brand/kb-logo-primary.svg' : '/brand/kb-logo-reversed.svg'}
      alt="Kisan Bandhu"
      width={819}
      height={156}
      unoptimized
      priority={priority}
      className={className}
    />
  );
}
